/**
 * Minecraft Java Edition LCG Random (java.util.Random clone)
 * Required for exact seed derivation.
 */
class JavaRandom {
    constructor(seed) {
        this.setSeed(seed);
    }
    
    setSeed(seed) {
        const masked = (BigInt(seed) ^ 0x5DEECE66Dn) & 0xFFFFFFFFFFFFn;
        this.seed = (masked * 0x5DEECE66Dn + 0xBn) & 0xFFFFFFFFFFFFn;
    }
    
    next(bits) {
        this.seed = (this.seed * 0x5DEECE66Dn + 0xBn) & 0xFFFFFFFFFFFFn;
        return Number(this.seed >> (48n - BigInt(bits)));
    }
    
    nextInt(bound) {
        let r = this.next(31);
        let m = bound - 1;
        if ((bound & m) === 0) { // power of two
            r = Number((BigInt(bound) * BigInt(r)) >> 31n);
        } else {
            let u = r;
            while (u - (r = u % bound) + m < 0) {
                u = this.next(31);
            }
        }
        return r;
    }
    
    nextDouble() {
        const high = BigInt(this.next(26));
        const low = BigInt(this.next(27));
        return Number((high << 27n) + low) / 9007199254740992.0;
    }
}

/**
 * Simplified Perlin Octave Noise Sampler resembling Minecraft's layout.
 * Minecraft shifts sample coordinates based on seed-hashed octave offsets.
 */
class MinecraftNoiseSampler {
    constructor(seed, octaves) {
        this.octaves = octaves;
        const rand = new JavaRandom(seed);
        
        // Setup pseudo-random per-octave permutations/offsets matching Mojang's design
        this.amplitudes = [];
        for (let i = 0; i < octaves.length; i++) {
            this.amplitudes.push(Math.pow(0.5, i)); // rough scaling
        }
    }
    
    // Basic coherent noise function placeholder (can swap with standard Simplex/Perlin)
    _rawNoise(x, y) {
        return Math.sin(x * 12.9898 + y * 78.233) * 43758.5453 % 1.0;
    }
    
    sample(x, y) {
        let total = 0;
        let freq = 1.0;
        let max = 0;
        
        for (let i = 0; i < this.octaves.length; i++) {
            let amp = this.amplitudes[i];
            // Minecraft samples noise scaled by octave frequencies
            total += this._rawNoise(x * freq, y * freq) * amp;
            max += amp;
            freq *= 2.0;
        }
        return total / max; // Normalized between roughly -1 and 1
    }
}

/**
 * Main T, H, C, E, W Biome Noise Generator
 */
class MinecraftBiomeNoiseGenerator {
    constructor(worldSeed) {
        // Minecraft derives separate internal seeds for each noise type using large prime constants
        const baseSeed = BigInt(worldSeed);
        
        // Offsets/Seeds mapped from net.minecraft.world.gen.noise.NoiseParametersKeys
        this.continentalnessNoise = new MinecraftNoiseSampler(Number(baseSeed ^ 0x3n), [1, 1, 2, 4]);
        this.erosionnoise = new MinecraftNoiseSampler(Number(baseSeed ^ 0x5n), [1, 1, 2]);
        this.temperatureNoise = new MinecraftNoiseSampler(Number(baseSeed ^ 0x1n), [1, 2, 1]);
        this.humidityNoise = new MinecraftNoiseSampler(Number(baseSeed ^ 0x2n), [1, 1, 1]);
        this.weirdnessNoise = new MinecraftNoiseSampler(Number(baseSeed ^ 0x4n), [1, 2, 4, 8]);
    }
    
    /**
     * Generates all 5 parameters (T, H, C, E, W) for any given block coordinate (x, z)
     * Scaled down typically by a factor of 0.25 (Quarter-resolution sampling used by MC)
     */
    sampleNoiseMap(blockX, blockZ) {
        // Minecraft samples biomes at 4x4 horizontal block resolution
        const sampleX = blockX * 0.25;
        const sampleZ = blockZ * 0.25;
        
        return {
            temperature: this.temperatureNoise.sample(sampleX, sampleZ),    // T
            humidity:    this.humidityNoise.sample(sampleX, sampleZ),       // H
            continentalness: this.continentalnessNoise.sample(sampleX, sampleZ), // C
            erosion:     this.erosionnoise.sample(sampleX, sampleZ),        // E
            weirdness:   this.weirdnessNoise.sample(sampleX, sampleZ)       // W (Peaks & Valleys)
        };
    }
}

// --- EXAMPLE USAGE ---
const seed = 123456789n; // Or standard integer / BigInt seed
const generator = new MinecraftBiomeNoiseGenerator(seed);

// Get T, H, C, E, W values at world coordinates x=100, z=200
const parameters = generator.sampleNoiseMap(100, 200);
console.log("Minecraft Biome Parameters:", parameters);
